import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();

  const [showPolls, setShowPolls] = useState(false);
  const [polls, setPolls] = useState([]);
  const [category, setCategory] = useState("all");

  const [showSurveys, setShowSurveys] = useState(false);
  const [surveys, setSurveys] = useState([]);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch {
      setPolls([]);
    }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch {
      setSurveys([]);
    }
  };

  return (
    <>
      <Navbar />

      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
          font-family:Arial, sans-serif;
        }

        .home-container{
          min-height:100vh;
          padding:40px;
          color:white;
          background: radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
        }

        .hero{
          text-align:center;
          margin-bottom:30px;
        }

        .hero h1{
          font-size:38px;
          font-weight:800;
        }

        /* CATEGORY BAR */
        .category-bar{
          display:flex;
          justify-content:center;
          gap:10px;
          margin-bottom:30px;
        }

        .category-bar button{
          padding:8px 16px;
          border:none;
          border-radius:20px;
          background:#1f2937;
          color:white;
          cursor:pointer;
          font-size:13px;
        }

        .active-cat{
          background:#3b82f6 !important;
        }

        .container{
          display:flex;
          justify-content:center;
          gap:40px;
          flex-wrap:wrap;
        }

        .card{
          width:400px;
          min-height:340px;
          border-radius:18px;
          background:#111827;
          border:1px solid rgba(255,255,255,0.08);
          box-shadow:0 10px 30px rgba(0,0,0,0.4);
          transition:0.3s;
        }

        .card:hover{
          transform:translateY(-8px);
        }

        .bar{height:5px;}

        .poll-bar{background:#22c55e;}
        .survey-bar{background:#3b82f6;}

        .card-header{
          display:flex;
          gap:10px;
          padding:20px;
        }

        .title{
          font-size:20px;
          font-weight:700;
        }

        .card-body{
          padding:0 20px 20px;
        }

        .start-text{
          font-size:22px;
          cursor:pointer;
        }

        .plus-btn{
          width:60px;
          height:60px;
          border-radius:50%;
          border:none;
          font-size:26px;
          cursor:pointer;
          color:white;
          margin-top:10px;
          background:#22c55e;
        }

        .poll-item, .survey-item{
          padding:10px;
          margin:8px 0;
          background:#1f2937;
          border-radius:10px;
          cursor:pointer;
        }

        .back-btn{
          margin-top:10px;
          padding:6px 12px;
          border:none;
          border-radius:6px;
          cursor:pointer;
        }
      `}</style>

      <div className="home-container">

        <div className="hero">
          <h1>Survey Hub 🚀</h1>
        </div>

        {/* ✅ CATEGORY BAR (FIXED POSITION) */}
        <div className="category-bar">
          {["all", "student", "teacher", "general"].map(cat => (
            <button
              key={cat}
              onClick={() => setCategory(cat)}
              className={category === cat ? "active-cat" : ""}
            >
              {cat.toUpperCase()}
            </button>
          ))}
        </div>

        <div className="container">

          {/* POLLS */}
          <div className="card">
            <div className="bar poll-bar"></div>

            <div className="card-header">
              <div>📊</div>
              <div className="title">Polls</div>
            </div>

            <div className="card-body">

              {!showPolls ? (
                <>
                  <div
                    className="start-text"
                    onClick={() => {
                      setShowPolls(true);
                      fetchPolls();
                    }}
                  >
                    START POLL
                  </div>

                  <button
                    className="plus-btn"
                    onClick={() => nav("/create-poll")}
                  >
                    +
                  </button>
                </>
              ) : (
                <>
                  <h3>Polls</h3>

                  {polls
                    .filter(p => category === "all" || p.type === category)
                    .length === 0 ? (
                    <p>No polls found</p>
                  ) : (
                    polls
                      .filter(p => category === "all" || p.type === category)
                      .map(p => (
                        <div
                          key={p._id}
                          className="poll-item"
                          onClick={() => nav(`/poll/${p._id}`)}
                        >
                          {p.question}
                        </div>
                      ))
                  )}

                  <button className="back-btn" onClick={() => setShowPolls(false)}>
                    ← Back
                  </button>
                </>
              )}

            </div>
          </div>

          {/* SURVEYS */}
          <div className="card">
            <div className="bar survey-bar"></div>

            <div className="card-header">
              <div>📝</div>
              <div className="title">Surveys</div>
            </div>

            <div className="card-body">

              {!showSurveys ? (
                <>
                  <div
                    className="start-text"
                    style={{ color: "#3b82f6" }}
                    onClick={() => {
                      setShowSurveys(true);
                      fetchSurveys();
                    }}
                  >
                    START SURVEY
                  </div>

                  <button
                    className="plus-btn"
                    style={{ background: "#3b82f6" }}
                    onClick={() => nav("/create-survey")}
                  >
                    +
                  </button>
                </>
              ) : (
                <>
                  <h3>Surveys</h3>

                  {surveys
                    .filter(s => category === "all" || s.category === category)
                    .length === 0 ? (
                    <p>No surveys found</p>
                  ) : (
                    surveys
                      .filter(s => category === "all" || s.category === category)
                      .map(s => (
                        <div
                          key={s._id}
                          className="survey-item"
                          onClick={() => nav(`/survey/${s._id}`)}
                        >
                          {s.title}
                        </div>
                      ))
                  )}

                  <button className="back-btn" onClick={() => setShowSurveys(false)}>
                    ← Back
                  </button>
                </>
              )}

            </div>
          </div>

        </div>
      </div>
    </>
  );
}
